package main

import (
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"
	"testing"
)

// Tests against REAL `terraform show -json` output, generated by
// scripts/smoke-plan.sh from testdata/real/<scenario>. The plan files are
// regenerated (new resource UUIDs) by the smoke workflow, so these assert
// on addresses, actions and counts, never on byte-exact output.

type realAnalysis struct {
	Summary struct {
		Mode    string `json:"mode"`
		Actions map[string]int
		Known   int `json:"known_after_apply"`
	} `json:"summary"`
	Notices []string `json:"notices"`
	Waves   []struct {
		Phase     string
		Number    int
		Resources []struct {
			Address         string
			NoConfiguration bool `json:"no_configuration"`
		}
	} `json:"waves"`
	WaveNotes []string `json:"wave_notes"`
	Parents   []struct {
		Address   string
		Kind      string
		Instances []struct{ Key, Action string }
	} `json:"parents"`
	Findings []struct {
		Address, Action, Reason string
		ReasonText              string   `json:"reason_text"`
		ReplacePaths            []string `json:"replace_paths"`
		IndexShift              bool     `json:"index_shift"`
	} `json:"findings"`
	Drift []struct {
		Address  string
		Action   string
		HighRisk bool `json:"high_risk"`
		Note     string
	} `json:"drift"`
	Changes []struct {
		Address   string
		Action    string
		MovedFrom string `json:"moved_from"`
		Import    bool   `json:"import"`
		ImportID  string `json:"import_id"`
		StateOnly bool   `json:"removed_from_state_only"`
		Attrs     []struct {
			Path string
			Kind string
			Diff *struct {
				Header         string
				Added, Removed int
				Total          int `json:"total_lines"`
			}
		}
	} `json:"changes"`
}

func realPlans(t *testing.T, scenario string) []string {
	t.Helper()
	files, _ := filepath.Glob("../../testdata/plans/real/" + scenario + "-tf*.json")
	if len(files) == 0 {
		t.Skipf("no real %s plan under testdata/plans/real (run scripts/smoke-plan.sh)", scenario)
	}
	return files
}

func analyzeReal(t *testing.T, plan string) (realAnalysis, map[string]string) {
	t.Helper()
	t.Setenv(envApplyAccount, "")
	outs := map[string]string{}
	for _, f := range []string{"json", "text", "markdown", "html"} {
		code, out, errs := runCLI("report", plan, "--format", f, "--no-color", "--tfapply-account-id", "111111111111")
		if code != exitOK {
			t.Fatalf("%s: exit %d: %s", f, code, errs)
		}
		outs[f] = out
	}
	var a realAnalysis
	if err := json.Unmarshal([]byte(outs["json"]), &a); err != nil {
		t.Fatal(err)
	}
	return a, outs
}

func (a realAnalysis) change(t *testing.T, addr string) int {
	t.Helper()
	for i, c := range a.Changes {
		if c.Address == addr {
			return i
		}
	}
	t.Fatalf("no change %s", addr)
	return -1
}

func TestRealSimplePlan(t *testing.T) {
	for _, plan := range realPlans(t, "simple") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			for action, want := range map[string]int{"create": 1, "update": 1, "replace": 1, "delete": 1} {
				if a.Summary.Actions[action] != want {
					t.Errorf("%s = %d, want %d", action, a.Summary.Actions[action], want)
				}
			}
			got := map[string]string{}
			for _, f := range a.Findings {
				got[f.Address] = f.Action + ":" + f.Reason
			}
			if len(got) != 2 || got["terraform_data.db"] != "replace:replace_because_cannot_update" || got["terraform_data.old"] != "delete:delete_because_no_resource_config" {
				t.Errorf("findings: %v", got)
			}
			for _, f := range a.Findings {
				if f.Address == "terraform_data.db" && strings.Join(f.ReplacePaths, ",") != "triggers_replace" {
					t.Errorf("replace_paths = %v (read from raw JSON)", f.ReplacePaths)
				}
			}
			text := outs["text"]
			if d := strings.Index(text, "== Danger =="); d < 0 || d > strings.Index(text, "== Changes by account ==") ||
				!strings.Contains(text, "Attribute change forces replacement: triggers_replace") || !strings.Contains(text, "Removed from config") {
				t.Errorf("danger section:\n%s", text)
			}
		})
	}
}

func TestRealComplexPlan(t *testing.T) {
	for _, plan := range realPlans(t, "complex") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)

			// Danger: exactly these four, with the right reasons.
			want := map[string]string{
				`terraform_data.db`:          "replace:replace_because_cannot_update",
				`terraform_data.subnet["b"]`: "delete:delete_because_each_key",
				`terraform_data.worker[2]`:   "delete:delete_because_count_index",
				`terraform_data.worker[3]`:   "delete:delete_because_count_index",
			}
			got := map[string]string{}
			for _, f := range a.Findings {
				got[f.Address] = f.Action + ":" + f.Reason
			}
			if len(got) != len(want) {
				t.Errorf("findings %v, want %v", got, want)
			}
			for k, v := range want {
				if got[k] != v {
					t.Errorf("finding %s = %q, want %q", k, got[k], v)
				}
			}

			// subnet["d"] is created; legacy is state-only, not a delete.
			if a.Changes[a.change(t, `terraform_data.subnet["d"]`)].Action != "create" {
				t.Error(`subnet["d"] should be a create`)
			}
			legacy := a.Changes[a.change(t, "terraform_data.legacy")]
			if !legacy.StateOnly || legacy.Action != "forget" {
				t.Errorf("legacy: %+v", legacy)
			}
			if _, inDanger := got["terraform_data.legacy"]; inDanger {
				t.Error("legacy (destroy = false) must not be a danger finding")
			}

			// Moved module resources are no-ops with moved_from, never delete+create.
			for _, name := range []string{"vpc", "route_table"} {
				c := a.Changes[a.change(t, "module.network_core.terraform_data."+name)]
				if c.MovedFrom != "module.network.terraform_data."+name || c.Action != "no-op" {
					t.Errorf("%s: %+v", name, c)
				}
			}
			for _, c := range a.Changes {
				if strings.HasPrefix(c.Address, "module.network") && (c.Action == "delete" || c.Action == "create") {
					t.Errorf("%s shown as %s", c.Address, c.Action)
				}
			}

			// creds: sensitive marker, and the secret appears in NO format.
			creds := a.Changes[a.change(t, "terraform_data.creds")]
			var sawSensitive bool
			for _, at := range creds.Attrs {
				if at.Path == "input" && at.Kind == "sensitive" {
					sawSensitive = true
				}
			}
			if !sawSensitive {
				t.Errorf("creds.input not shown as sensitive: %+v", creds.Attrs)
			}
			for format, out := range outs {
				for _, secret := range []string{"hunter2", "hunter3"} {
					if strings.Contains(out, secret) {
						t.Errorf("%s output leaks %q", format, secret)
					}
				}
			}

			// user_data: base64 decoded, only the changed lines of 401.
			ud := a.Changes[a.change(t, "terraform_data.user_data")]
			var longAttr bool
			for _, at := range ud.Attrs {
				if at.Path == "input" && at.Kind == "long" && at.Diff != nil {
					longAttr = at.Diff.Added == 2 && at.Diff.Removed == 2 && at.Diff.Total == 401
				}
			}
			if !longAttr {
				t.Errorf("user_data input diff: %+v", ud.Attrs)
			}

			// Known-after-apply values are a count, never listed or dumped.
			if a.Summary.Known == 0 {
				t.Error("known_after_apply count missing")
			}
			for _, c := range a.Changes {
				for _, at := range c.Attrs {
					if at.Kind == "unknown" {
						t.Errorf("%s: unknown attribute %s listed inline", c.Address, at.Path)
					}
				}
			}
			for format, out := range outs {
				if format == "html" {
					continue // the HTML report legitimately embeds full values behind a toggle
				}
				for _, line := range strings.Split(out, "\n") {
					if len(line) > 400 {
						t.Errorf("%s output has a %d-character line: %.60s...", format, len(line), line)
					}
				}
				if strings.Contains(out, "(absent)") && strings.Contains(out, "output[") {
					t.Errorf("%s output has spurious output[...] -> (absent) lines", format)
				}
			}
		})
	}
}

func findings(a realAnalysis) map[string]string {
	m := map[string]string{}
	for _, f := range a.Findings {
		m[f.Address] = f.Action + ":" + f.Reason
	}
	return m
}

func TestRealDestroyPlan(t *testing.T) {
	for _, plan := range realPlans(t, "destroy") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			if a.Summary.Mode != "destroy" || a.Summary.Actions["delete"] != 4 {
				t.Errorf("mode %q, actions %v", a.Summary.Mode, a.Summary.Actions)
			}
			if len(a.Findings) != 4 {
				t.Fatalf("%d findings, want 4", len(a.Findings))
			}
			for _, f := range a.Findings {
				if !strings.Contains(f.ReasonText, "Destroy plan") {
					t.Errorf("%s: reason %q (Terraform sends no action_reason on a destroy plan)", f.Address, f.ReasonText)
				}
			}
			if len(a.Notices) == 0 || !strings.Contains(outs["text"], "Destroy plan: applying destroys") {
				t.Error("destroy notice missing")
			}
			if strings.Contains(outs["text"], "no reason reported") {
				t.Error("destroy plan deletes look like missing data")
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "delete"); code != exitFailOn {
				t.Errorf("--fail-on delete: exit %d", code)
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "replace,drift"); code != exitOK {
				t.Errorf("--fail-on replace,drift: exit %d", code)
			}
		})
	}
}

func TestRealImportPlan(t *testing.T) {
	for _, plan := range realPlans(t, "import") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			imp := a.Changes[a.change(t, "terraform_data.imp")]
			if !imp.Import || imp.ImportID == "" || imp.Action != "update" {
				t.Errorf("imp: %+v", imp)
			}
			if other := a.Changes[a.change(t, "terraform_data.other")]; other.Import {
				t.Error("other must not be an import")
			}
			if !strings.Contains(outs["text"], "import + update") || !strings.Contains(outs["markdown"], "import + update") {
				t.Errorf("import label missing:\n%s", outs["text"])
			}
			if len(a.Findings) != 0 {
				t.Errorf("import + update is not dangerous: %v", findings(a))
			}
		})
	}
}

// Every action_reason keyword here comes from a real plan.
func TestRealReasonsPlan(t *testing.T) {
	for _, plan := range realPlans(t, "reasons") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			want := map[string]string{
				"terraform_data.follower":               "replace:replace_by_triggers",
				"terraform_data.requested":              "replace:replace_by_request",
				"terraform_data.tainted":                "replace:replace_because_tainted",
				"terraform_data.single":                 "delete:delete_because_wrong_repetition",
				"module.gone.terraform_data.inner":      "delete:delete_because_no_resource_config",
				`module.mods["b"].terraform_data.inner`: "delete:delete_because_no_module",
			}
			got := findings(a)
			if len(got) != len(want) {
				t.Errorf("findings %v", got)
			}
			for k, v := range want {
				if got[k] != v {
					t.Errorf("%s = %q, want %q", k, got[k], v)
				}
			}
			for _, f := range a.Findings {
				if f.ReasonText == "" || f.ReasonText == f.Reason {
					t.Errorf("%s: reason %q is not plain English", f.Address, f.ReasonText)
				}
				if f.Address == "terraform_data.single" && !f.IndexShift {
					t.Error("count/for_each switch should warn")
				}
			}
			// An implicit single -> count move is a move, not delete + create.
			if c := a.Changes[a.change(t, "terraform_data.counted[0]")]; c.MovedFrom != "terraform_data.counted" || c.Action != "no-op" {
				t.Errorf("counted[0]: %+v", c)
			}
			for _, text := range []string{outs["text"], outs["markdown"]} {
				for _, phrase := range []string{"replace_triggered_by dependency changed", "Replacement requested with -replace", "Resource is tainted",
					"Resource switched between count/for_each/single", "Whole module removed or its call changed"} {
					if !strings.Contains(text, phrase) {
						t.Errorf("missing %q", phrase)
					}
				}
			}
		})
	}
}

func TestRealDriftPlan(t *testing.T) {
	for _, plan := range realPlans(t, "drift") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			if a.Summary.Mode != "normal" || len(a.Drift) != 2 {
				t.Fatalf("mode %q, drift %d", a.Summary.Mode, len(a.Drift))
			}
			for _, d := range a.Drift {
				if d.Action != "delete" || d.Note != "Deleted outside Terraform" {
					t.Errorf("drift %+v", d)
				}
			}
			if !strings.Contains(outs["text"], "- local_file.config") {
				t.Errorf("a resource deleted outside Terraform should use the delete symbol:\n%s", outs["text"])
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "drift"); code != exitFailOn {
				t.Errorf("--fail-on drift: exit %d", code)
			}
		})
	}
}

// A refresh-only plan has no resource_changes at all in the real JSON.
func TestRealRefreshOnlyPlan(t *testing.T) {
	for _, plan := range realPlans(t, "refresh-only") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			a, outs := analyzeReal(t, plan)
			if a.Summary.Mode != "refresh-only" || len(a.Changes) != 0 || len(a.Drift) != 2 {
				t.Errorf("mode %q, changes %d, drift %d", a.Summary.Mode, len(a.Changes), len(a.Drift))
			}
			for action, n := range a.Summary.Actions {
				if n != 0 {
					t.Errorf("%s = %d in a refresh-only plan", action, n)
				}
			}
			if len(a.Notices) == 0 || !strings.Contains(outs["text"], "Refresh-only plan: applying only updates state") {
				t.Error("refresh-only notice missing")
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "drift"); code != exitFailOn {
				t.Errorf("--fail-on drift: exit %d", code)
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "delete,replace"); code != exitOK {
				t.Errorf("--fail-on delete,replace: exit %d (drift is not a planned delete)", code)
			}
		})
	}
}

// For a module handed `providers = { local = local.alt }`, Terraform writes
// the RESOLVED root key ("local.alt") as the module resource's
// provider_config_key (not a module-prefixed "net:local"), so account
// resolution sees the right provider.
func TestRealModuleProviderPlan(t *testing.T) {
	for _, plan := range realPlans(t, "module-provider") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			t.Setenv(envApplyAccount, "")
			code, out, errs := runCLI("report", plan, "--format", "json", "--tfapply-account-id", "111111111111", "--account", "alt=222222222222")
			if code != exitOK {
				t.Fatalf("exit %d: %s", code, errs)
			}
			var a struct {
				Groups []struct {
					Key, Account, Source string
					Cross                bool `json:"cross_account"`
					Addresses            []string
				}
			}
			if err := json.Unmarshal([]byte(out), &a); err != nil {
				t.Fatal(err)
			}
			byKey := map[string][]string{}
			for _, g := range a.Groups {
				byKey[g.Key] = g.Addresses
				switch g.Key {
				case "local":
					if g.Account != "111111111111" || g.Source != "apply_account" || g.Cross {
						t.Errorf("default group: %+v", g)
					}
				case "local.alt":
					if g.Account != "222222222222" || g.Source != "flag" || !g.Cross {
						t.Errorf("alt group: %+v", g)
					}
				default:
					t.Errorf("unexpected group %q", g.Key)
				}
			}
			if !strings.Contains(strings.Join(byKey["local.alt"], " "), "module.net.local_file.inner") {
				t.Errorf("module resource not grouped under local.alt: %v", byKey)
			}
			if strings.Contains(strings.Join(byKey["local"], " "), "module.net") {
				t.Error("module resource landed in the default provider group")
			}
			// Without any account information the alias is unresolved, not a guess.
			_, text, _ := runCLI("report", plan, "--no-color")
			if !strings.Contains(text, "local.alt: target account unresolved (alias: alt)") {
				t.Errorf("alias fallback label missing:\n%s", text)
			}
		})
	}
}

// The documented JSON schema promises arrays, never null. Check every array
// field of every plan's JSON report.
func TestJSONArraysAreNeverNull(t *testing.T) {
	t.Setenv(envApplyAccount, "")
	arrayKeys := map[string]bool{"notices": true, "findings": true, "drift": true, "groups": true, "changes": true,
		"attrs": true, "warnings": true, "addresses": true, "parents": true, "waves": true, "wave_notes": true,
		"cycles": true, "resources": true, "instances": true, "actions": true}
	var walk func(path string, v any)
	walk = func(path string, v any) {
		switch x := v.(type) {
		case map[string]any:
			for k, c := range x {
				if arrayKeys[k] && c == nil {
					t.Errorf("%s.%s is null", path, k)
				}
				walk(path+"."+k, c)
			}
		case []any:
			for i, c := range x {
				walk(fmt.Sprintf("%s[%d]", path, i), c)
			}
		}
	}
	var plans []string
	for _, pattern := range []string{"../../testdata/plans/*.json", "../../testdata/plans/real/*.json"} {
		m, _ := filepath.Glob(pattern)
		plans = append(plans, m...)
	}
	for _, plan := range plans {
		code, out, errs := runCLI("report", plan, "-f", "json")
		if code != exitOK {
			t.Fatalf("%s: exit %d: %s", plan, code, errs)
		}
		var doc any
		if err := json.Unmarshal([]byte(out), &doc); err != nil {
			t.Fatal(err)
		}
		walk(filepath.Base(plan), doc)
	}
}

// Real AWS provider plan, produced against floci (a local AWS emulator) so
// that no real credentials are involved. This is the first real plan with
// assume_role: a literal role ARN, a variable-based one, an alias without
// assume_role, an alias pinned with allowed_account_ids, a module handed an
// aliased provider, and aws_caller_identity data sources in prior_state.
func TestRealAWSAssumeRolePlan(t *testing.T) {
	for _, plan := range realPlans(t, "aws-assume-role") {
		t.Run(filepath.Base(plan), func(t *testing.T) {
			t.Setenv(envApplyAccount, "")
			code, out, errs := runCLI("report", plan, "-f", "json")
			if code != exitOK || errs != "" {
				t.Fatalf("exit %d: %s", code, errs)
			}
			var a struct {
				ApplyAccount struct {
					ID, Source, Via string
				} `json:"apply_account"`
				Summary struct {
					Warnings int
				}
				Groups []struct {
					Key, Account, Source string
					Cross                bool `json:"cross_account"`
					Addresses            []string
				}
				Findings []struct {
					Address   string
					DriftAlso bool `json:"drift_also"`
				}
				Drift   []struct{ Address string }
				Changes []struct {
					Address  string
					Warnings []struct{ Kind, Path, Message string }
					Attrs    []struct {
						Path, Kind    string
						Before, After json.RawMessage
					}
				}
			}
			if err := json.Unmarshal([]byte(out), &a); err != nil {
				t.Fatal(err)
			}

			// The apply account is inferred from the default provider's
			// aws_caller_identity in prior_state.
			if a.ApplyAccount.ID != "999999999999" || a.ApplyAccount.Source != "inferred" || a.ApplyAccount.Via != "caller_identity" {
				t.Errorf("apply account %+v", a.ApplyAccount)
			}
			want := map[string][3]any{ // key -> account, source, cross-account
				"aws":         {"999999999999", "caller_identity", false},
				"aws.audit":   {"999999999999", "allowed_account_ids", false},
				"aws.prod":    {"111111111111", "role_arn", true}, // literal ARN wins over the prod caller identity
				"aws.sandbox": {"999999999999", "apply_account", false},
				"aws.staging": {"222222222222", "role_arn_variable", true},
			}
			groups := map[string][]string{}
			for _, g := range a.Groups {
				w, ok := want[g.Key]
				if !ok {
					t.Errorf("unexpected group %q", g.Key)
					continue
				}
				if g.Account != w[0] || g.Source != w[1] || g.Cross != w[2] {
					t.Errorf("%s: %s via %s cross=%v, want %v", g.Key, g.Account, g.Source, g.Cross, w)
				}
				groups[g.Key] = g.Addresses
			}
			if len(a.Groups) != len(want) {
				t.Errorf("%d groups, want %d", len(a.Groups), len(want))
			}
			// A module handed providers = { aws = aws.prod } lands in aws.prod.
			if !strings.Contains(strings.Join(groups["aws.prod"], " "), "module.net.aws_sqs_queue.inner") {
				t.Errorf("module resource not in aws.prod: %v", groups)
			}

			// The one real cross-account reference: a subscription created by
			// the runner pointing at a topic in the prod account.
			var warned []string
			for _, c := range a.Changes {
				for _, w := range c.Warnings {
					warned = append(warned, c.Address+" "+w.Path)
					if !strings.Contains(w.Message, "111111111111") || !strings.Contains(w.Message, "999999999999") {
						t.Errorf("warning message %q", w.Message)
					}
				}
			}
			if len(warned) != 1 || warned[0] != "aws_sns_topic_subscription.cross topic_arn" || a.Summary.Warnings != 1 {
				t.Errorf("warnings = %v (count %d)", warned, a.Summary.Warnings)
			}

			// Only the module queue replacement is dangerous. The provider's
			// null -> {} tags read-back is not drift.
			if len(a.Findings) != 1 || a.Findings[0].Address != "module.net.aws_sqs_queue.inner" || a.Findings[0].DriftAlso {
				t.Errorf("findings %+v", a.Findings)
			}
			if len(a.Drift) != 0 {
				t.Errorf("drift %v: null vs empty tags must not count", a.Drift)
			}
			if code, _, _ := runCLI("report", plan, "--fail-on", "drift,unresolved"); code != exitOK {
				t.Errorf("--fail-on drift,unresolved: exit %d, want 0", code)
			}

			// The SSM parameter value is sensitive in the AWS provider schema.
			for _, c := range a.Changes {
				if c.Address != "aws_ssm_parameter.sandbox" {
					continue
				}
				var sawSensitive bool
				for _, at := range c.Attrs {
					if at.Path == "value" {
						sawSensitive = at.Kind == "sensitive" && len(at.Before) == 0 && len(at.After) == 0
					}
				}
				if !sawSensitive {
					t.Errorf("ssm value not shown as sensitive: %+v", c.Attrs)
				}
			}
		})
	}
}

// waveOf returns the "phase N" a configuration address is in, or "".
func (a realAnalysis) waveOf(addr string) string {
	for _, w := range a.Waves {
		for _, r := range w.Resources {
			if r.Address == addr {
				return fmt.Sprintf("%s %d", w.Phase, w.Number)
			}
		}
	}
	return ""
}

func TestRealWavesFromConfiguration(t *testing.T) {
	for _, f := range realPlans(t, "complex") {
		a, outs := analyzeReal(t, f)
		for addr, want := range map[string]string{
			"terraform_data.db":     "apply 1",
			"terraform_data.app":    "apply 2",
			"terraform_data.lb":     "apply 2",
			"terraform_data.worker": "destroy 1",
		} {
			if got := a.waveOf(addr); got != want {
				t.Errorf("%s: wave %q, want %q", addr, got, want)
			}
		}
		found := false
		for _, p := range a.Parents {
			if p.Address == "terraform_data.worker" && p.Kind == "count" && len(p.Instances) == 4 {
				found = true
			}
		}
		if !found {
			t.Errorf("no count parent for terraform_data.worker: %+v", a.Parents)
		}
		for _, format := range []string{"text", "markdown", "html"} {
			if !strings.Contains(outs[format], "apply wave 2") {
				t.Errorf("%s output has no apply wave 2", format)
			}
		}
	}
	for _, f := range realPlans(t, "reasons") {
		a, _ := analyzeReal(t, f)
		none := 0
		for _, w := range a.Waves {
			for _, r := range w.Resources {
				if r.NoConfiguration {
					none++
				}
			}
		}
		if none == 0 {
			t.Errorf("reasons: expected a destroyed resource removed from configuration")
		}
	}
}

// The "rereview" scenario is a real before/after pair: the same state planned
// against v2 and then against v3 of the configuration.
func TestRealPlanDiff(t *testing.T) {
	before := realPlans(t, "rereview")
	afterFiles, _ := filepath.Glob("../../testdata/plans/real/rereview-after-tf*.json")
	if len(afterFiles) == 0 {
		t.Skip("no rereview-after plan")
	}
	t.Setenv(envApplyAccount, "")
	code, out, errs := runCLI("diff", before[0], afterFiles[0], "-f", "json", "--tfapply-account-id", "111111111111")
	if code != exitOK {
		t.Fatalf("exit %d: %s", code, errs)
	}
	var d struct {
		Added, Removed, Changed []struct {
			Address     string
			Differences []string
			Danger      bool
			Defused     bool
		}
		NewDanger []string `json:"new_danger"`
		Defused   []string
		Unchanged int
	}
	if err := json.Unmarshal([]byte(out), &d); err != nil {
		t.Fatal(err)
	}
	names := func(es []struct {
		Address     string
		Differences []string
		Danger      bool
		Defused     bool
	}) string {
		var a []string
		for _, e := range es {
			a = append(a, e.Address)
		}
		return strings.Join(a, ",")
	}
	if got := names(d.Added); got != "terraform_data.cache[2],terraform_data.legacy" {
		t.Errorf("added %s", got)
	}
	if got := names(d.Removed); got != "terraform_data.db,terraform_data.queue" {
		t.Errorf("removed %s", got)
	}
	if got := names(d.Changed); got != "terraform_data.app" || !strings.Contains(strings.Join(d.Changed[0].Differences, ";"), `now "v1" => "v3"`) {
		t.Errorf("changed %s %v", got, d.Changed)
	}
	if strings.Join(d.NewDanger, ",") != "terraform_data.legacy" || strings.Join(d.Defused, ",") != "terraform_data.db" {
		t.Errorf("danger %v defused %v", d.NewDanger, d.Defused)
	}

	// Same plan twice: no differences.
	code, out, _ = runCLI("diff", before[0], before[0])
	if code != exitOK || !strings.Contains(out, "No differences") {
		t.Errorf("self diff: exit %d\n%s", code, out)
	}

	// --fail-on-new-danger exits 1 only when the new plan adds danger; the
	// report is still written first.
	code, out, errs = runCLI("diff", before[0], afterFiles[0], "--fail-on-new-danger", "--tfapply-account-id", "111111111111")
	if code != exitFailOn || !strings.Contains(errs, "new danger: terraform_data.legacy") || !strings.Contains(out, "New danger") {
		t.Errorf("fail-on-new-danger: exit %d, stderr %q", code, errs)
	}
	code, _, _ = runCLI("diff", afterFiles[0], before[0], "--fail-on-new-danger", "--tfapply-account-id", "111111111111")
	if code != exitFailOn { // going back re-introduces the db replace
		t.Errorf("reverse diff: exit %d, want %d (db is replaced again)", code, exitFailOn)
	}
	code, _, _ = runCLI("diff", before[0], before[0], "--fail-on-new-danger")
	if code != exitOK {
		t.Errorf("identical plans failed --fail-on-new-danger: %d", code)
	}
}

func TestDiffRejectsBadInput(t *testing.T) {
	for name, args := range map[string][]string{
		"two stdin":  {"diff", "-", "-"},
		"html":       {"diff", "a", "b", "-f", "html"},
		"missing":    {"diff", "nope.json", "nope2.json"},
		"one plan":   {"diff", "a"},
		"two format": {"diff", "a", "b", "-f", "text", "-f", "json"},
	} {
		if code, _, _ := runCLI(args...); code == exitOK {
			t.Errorf("%s: exit 0", name)
		}
	}
}
